from pathlib import Path

root=Path(__file__).parent
index=root/'static'/'index.html'
html=index.read_text()

css=r'''
<style id="kai-stock-runtime-v16-style">
.kai-s16-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:0 0 10px;padding:10px 12px;border:1px solid #dce9ed;border-radius:11px;background:#f9fcfd}
.kai-s16-metrics{display:flex;gap:14px;flex-wrap:wrap}.kai-s16-metrics span{font-size:11px;color:var(--muted)}.kai-s16-metrics b{font-size:14px;color:#173f4a;margin-right:4px}
.kai-s16-actions{display:flex;gap:8px;flex-wrap:wrap}.kai-s16-btn{border:1px solid #cfe0e4;background:#fff;color:#173f4a;border-radius:8px;padding:7px 10px;font-weight:750;font-size:11px;cursor:pointer}.kai-s16-btn.primary{background:#173f4a;color:#fff;border-color:#173f4a}
.kai-s16-intel{margin:0 0 12px;border:1px solid #dce9ed;border-radius:11px;background:#fff;overflow:hidden}.kai-s16-intel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;background:#f8fcfd}.kai-s16-intel-head h3{margin:0;font-size:14px;color:#173f4a}.kai-s16-intel-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:10px}.kai-s16-intel-grid>div{border:1px solid #e5eef0;border-radius:9px;padding:9px}.kai-s16-intel-grid b{display:block;font-size:18px;color:#173f4a}.kai-s16-intel-grid span{font-size:10px;color:var(--muted)}
.kai-s16-cats{display:none;padding:0 10px 10px;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.kai-s16-cats.open{display:grid}.kai-s16-cat{border:1px solid #e5eef0;border-radius:9px;padding:8px;background:#fff;text-align:left;cursor:pointer}.kai-s16-cat b{display:block;font-size:15px;color:#173f4a}.kai-s16-cat span{font-size:10px;color:#315763}.kai-s16-cat small{display:block;font-size:9px;color:var(--muted);margin-top:2px}
#kai-stock-s16-search-wrap{position:relative;min-width:0;flex:1}.kai-stock-s16-dropdown{position:absolute;left:0;right:0;top:calc(100% + 5px);z-index:5000;background:#fff;border:1px solid #d7e6ea;border-radius:10px;box-shadow:0 12px 30px rgba(16,42,56,.18);max-height:310px;overflow-y:auto;overscroll-behavior:contain;scrollbar-gutter:stable;display:none;padding:5px}.kai-stock-s16-dropdown.open{display:block}.kai-stock-s16-option{display:block;width:100%;border:0;border-bottom:1px solid #edf3f5;background:#fff;text-align:left;padding:9px 10px;border-radius:7px;cursor:pointer}.kai-stock-s16-option:hover{background:#f4fbfd}.kai-stock-s16-option b{display:block;font-size:12px}.kai-stock-s16-option small{display:block;font-size:10px;color:var(--muted);margin-top:2px}.kai-stock-s16-empty{padding:10px;color:var(--muted);font-size:11px}
.kai-s16-import{grid-column:1/-1;border:1px dashed #9fc8d2;border-radius:11px;background:#f7fcfd;padding:11px}.kai-s16-import-actions{display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin-top:8px}.kai-s16-import-preview{display:none;margin-top:8px;max-height:220px;overflow:auto;border:1px solid #dce9ed;border-radius:8px;background:#fff}.kai-s16-import-preview table{min-width:720px;margin:0}.kai-s16-status{font-size:11px;color:#315763;margin-top:6px}.kai-s16-status.error{color:#a32b2b}
@media(max-width:760px){.kai-s16-intel-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.kai-s16-cats{grid-template-columns:1fr 1fr}.kai-s16-actions{width:100%}.kai-s16-btn{flex:1 1 auto}}@media(max-width:520px){.kai-s16-cats{grid-template-columns:1fr}}
</style>
'''

js=r'''
<script id="kai-stock-runtime-v16-script">
(()=>{
 const CATEGORIES=['Original Jerseys','Fan/Net Version Jerseys','Copy Jerseys','Vintage Jerseys',"Children's Jersey Sets",'Shorts','2-Piece Play Sets','Body Armour','Baseball Jerseys','Lakers/Basketball Vests','Plain Jumpers','Other Sportswear'];
 const VERSIONS=['Original','Fan/Net Version','Copy','Vintage','N/A'];
 const SIZES=['XS','S','M','L','XL','XXL','XXXL','Kids S','Kids M','Kids L'];
 const KITS=['Home','Away','Third','N/A'];
 const PAY=['Paid','Partially Paid','Unpaid'];
 let expanded=false,catOpen=false,importRows=[];
 const isStock=()=>typeof page!=='undefined'&&page==='Stock';
 const units=p=>Object.values(p?.alloc||{}).reduce((a,v)=>a+Number(v||0),0);
 const minLevel=p=>{const n=Number(p?.minStock);return Number.isFinite(n)&&n>=0?n:5};
 const pName=p=>String(p?.name||p?.club||p?.id||'Product');
 const pCategory=p=>String(p?.category||'Other Sportswear');
 const searchText=p=>[p?.id,p?.name,p?.category,p?.club,p?.grade,p?.kit,p?.season,p?.size,p?.color].filter(Boolean).join(' ').toLowerCase();
 const opts=(xs,val='')=>xs.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('');
 function title(){if(!isStock())return;document.querySelectorAll('h1,h2').forEach(h=>{if(['Jersey stock','Products & stock','Stock'].includes(h.textContent.trim()))h.textContent='Stock products'})}
 function filters(){return {q:String(typeof search==='undefined'?'':search||'').trim().toLowerCase(),cat:document.querySelector('#excel-category')?.value||'',grade:document.querySelector('#grade')?.value||'',size:document.querySelector('#size')?.value||''}}
 function selectedProducts(){const f=filters();return (state?.products||[]).filter(p=>(!f.q||searchText(p).includes(f.q))&&(!f.cat||pCategory(p)===f.cat)&&(!f.grade||String(p.grade||'')===f.grade)&&(!f.size||String(p.size||'')===f.size))}
 function status(p){const q=units(p);return q===0?'OUT':q<=minLevel(p)?'RESTOCK':'OK'}
 function ensureCategoryFilter(){if(!isStock())return;const box=document.querySelector('.filters'),grade=document.querySelector('#grade');if(!box)return;if(!document.querySelector('#excel-category')){const s=document.createElement('select');s.id='excel-category';s.innerHTML='<option value="">All categories</option>'+opts(CATEGORIES);s.addEventListener('change',()=>stockTable());grade?box.insertBefore(s,grade):box.appendChild(s)}}
 function renderTable(){
   if(!isStock())return;title();ensureCategoryFilter();const host=document.querySelector('#stock-table');if(!host)return;
   const ps=selectedProducts(),total=ps.reduce((a,p)=>a+units(p),0),low=ps.filter(p=>status(p)==='RESTOCK').length,out=ps.filter(p=>status(p)==='OUT').length;
   const all=state?.products||[],allTotal=all.reduce((a,p)=>a+units(p),0),active=all.filter(p=>units(p)>0).length,allLow=all.filter(p=>status(p)==='RESTOCK').length,allOut=all.filter(p=>status(p)==='OUT').length;
   const cats=CATEGORIES.map(name=>{const arr=all.filter(p=>pCategory(p)===name);return {name,units:arr.reduce((a,p)=>a+units(p),0),variants:arr.length}});
   const rows=expanded?`<div class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Club / Country</th><th>Version</th><th>Kit</th><th>Season</th><th>Size</th><th class="end">Shop 1</th><th class="end">Shop 2</th><th class="end">Total</th><th>Status</th></tr></thead><tbody>${ps.map(p=>{const st=status(p);return `<tr><td><b>${esc(pName(p))}</b><small>${esc(p.id||'')}</small></td><td>${esc(pCategory(p))}</td><td>${esc(p.club||'—')}</td><td>${esc(p.grade||'—')}</td><td>${esc(p.kit||'—')}</td><td>${esc(p.season||'—')}</td><td><span class="badge">${esc(p.size||'—')}</span></td><td class="end">${typeof qty==='function'?qty(p,'Shop 1'):Number(p.alloc?.['Shop 1']||0)}</td><td class="end">${typeof qty==='function'?qty(p,'Shop 2'):Number(p.alloc?.['Shop 2']||0)}</td><td class="end"><b>${units(p)}</b></td><td><span class="excel-stock-tag ${st==='RESTOCK'?'low':st==='OUT'?'out':''}">${st}</span><span class="excel-stock-sub">Min ${minLevel(p)}</span></td></tr>`}).join('')}</tbody></table></div>${!ps.length?'<div class="empty">No products match those filters.</div>':''}`:'';
   host.innerHTML=`<div class="kai-s16-toolbar"><div class="kai-s16-metrics"><span><b>${total}</b>units in view</span><span><b>${ps.length}</b>variants</span><span><b>${low}</b>restock</span><span><b>${out}</b>out</span></div><div class="kai-s16-actions"><button type="button" class="kai-s16-btn primary" id="kai-s16-expand">${expanded?'Full stock open':'View all stock / Expand'}</button>${expanded?'<button type="button" class="kai-s16-btn" id="kai-s16-collapse">Collapse</button>':''}<button type="button" class="kai-s16-btn" id="kai-s16-cats">${catOpen?'Hide category breakdown':'Show category breakdown'}</button></div></div><section class="kai-s16-intel"><div class="kai-s16-intel-head"><h3>Stock intelligence</h3><span class="tiny">Stock products overview</span></div><div class="kai-s16-intel-grid"><div><b>${allTotal}</b><span>Total units</span></div><div><b>${active}</b><span>Active variants</span></div><div><b>${allLow}</b><span>Need restocking</span></div><div><b>${allOut}</b><span>Out of stock</span></div></div><div class="kai-s16-cats ${catOpen?'open':''}">${cats.map(c=>`<button type="button" class="kai-s16-cat" data-cat="${esc(c.name)}"><b>${c.units}</b><span>${esc(c.name)}</span><small>${c.variants} variant${c.variants===1?'':'s'}</small></button>`).join('')}</div></section>${rows}`;
   host.querySelector('#kai-s16-expand')?.addEventListener('click',()=>{expanded=true;if(typeof search!=='undefined')search='';const si=document.querySelector('#search');if(si)si.value='';for(const id of ['excel-category','grade','size']){const el=document.getElementById(id);if(el)el.value=''}renderTable()});
   host.querySelector('#kai-s16-collapse')?.addEventListener('click',()=>{expanded=false;renderTable()});
   host.querySelector('#kai-s16-cats')?.addEventListener('click',()=>{catOpen=!catOpen;renderTable()});
   host.querySelectorAll('[data-cat]').forEach(b=>b.addEventListener('click',()=>{const s=document.querySelector('#excel-category');if(s){s.value=b.dataset.cat||'';expanded=true;renderTable()}}));
 }
 stockTable=function(){renderTable()};
 function dropdownRows(input,d){const q=input.value.trim().toLowerCase(),all=state?.products||[],rows=all.filter(p=>!q||searchText(p).includes(q)).slice(0,40);d.innerHTML=rows.length?rows.map((p,i)=>`<button type="button" class="kai-stock-s16-option" data-i="${i}"><b>${esc(pName(p))}</b><small>${esc([p.id,p.category,p.grade,p.size,`${units(p)} units`].filter(Boolean).join(' · '))}</small></button>`).join(''):'<div class="kai-stock-s16-empty">No matching product.</div>';d.classList.add('open');d.querySelectorAll('[data-i]').forEach((b,i)=>b.onclick=()=>{const p=rows[i];if(!p)return;input.value=pName(p);search=input.value;expanded=true;d.classList.remove('open');renderTable()})}
 function mountSearch(){if(!isStock())return;const input=document.querySelector('#search');if(!input||input.dataset.kaiS16==='1')return;input.dataset.kaiS16='1';let wrap=input.parentElement;if(!wrap||wrap.id!=='kai-stock-s16-search-wrap'){const w=document.createElement('div');w.id='kai-stock-s16-search-wrap';input.parentNode.insertBefore(w,input);w.appendChild(input);wrap=w}let d=document.querySelector('#kai-stock-s16-dropdown');if(!d){d=document.createElement('div');d.id='kai-stock-s16-dropdown';d.className='kai-stock-s16-dropdown';wrap.appendChild(d)}input.autocomplete='off';input.placeholder='Search stock products: name, code, category, club, version, kit, season, size…';input.addEventListener('focus',()=>dropdownRows(input,d));input.addEventListener('input',()=>{search=input.value;dropdownRows(input,d);renderTable()});input.addEventListener('keydown',e=>{if(e.key==='Escape')d.classList.remove('open')});d.addEventListener('wheel',e=>e.stopPropagation(),{passive:true});d.addEventListener('touchmove',e=>e.stopPropagation(),{passive:true});d.addEventListener('pointerdown',e=>e.stopPropagation());document.addEventListener('pointerdown',e=>{if(isStock()&&!wrap.contains(e.target))d.classList.remove('open')},true)}
 function formDataValues(x){if(x instanceof FormData)return Object.fromEntries(x.entries());if(x instanceof HTMLFormElement)return Object.fromEntries(new FormData(x).entries());try{return Object.fromEntries(x)}catch(_){return {}}}
 function custom(v,n){return String(v[n]==='__custom__'?v[n+'Custom']||'':v[n]||'').trim()}
 function resolveExisting(raw){const q=String(raw||'').trim().toLowerCase();return (state?.products||[]).find(p=>String(p.id||'').toLowerCase()===q)||(state?.products||[]).find(p=>searchText(p)===q)||(state?.products||[]).find(p=>searchText(p).includes(q))}
 function openStockForm(kindDefault='existing'){
   importRows=[];const products=state?.products||[],list=products.map(p=>`<option value="${esc(p.id)}">${esc([pName(p),pCategory(p),p.club,p.grade,p.size].filter(Boolean).join(' · '))}</option>`).join('');
   if(typeof showForm!=='function'){toast?.('Stock form is unavailable.');return}
   showForm(kindDefault==='new'?'Add stock product':'Receive / add stock',`<div class="kai-s16-import"><b>Bulk stock import</b><div class="tiny">Upload Excel (.xlsx) or Word (.docx), preview recognized rows, then import them to the selected counter.</div><div class="kai-s16-import-actions"><input id="kai-s16-file" type="file" accept=".xlsx,.docx"><button type="button" id="kai-s16-read">Read & preview</button><button type="button" id="kai-s16-import" class="primary" disabled>Import stock</button></div><div id="kai-s16-import-status" class="kai-s16-status">Or enter one stock delivery below.</div><div id="kai-s16-import-preview" class="kai-s16-import-preview"></div></div><div class="full note"><b>Stock receiving.</b> Buying cost is recorded for this delivery. Selling price is entered only when the item is sold.</div><label class="full">Stock type<select name="kind"><option value="existing" ${kindDefault==='existing'?'selected':''}>Existing product / variant</option><option value="new" ${kindDefault==='new'?'selected':''}>New product / variant</option></select></label><label class="full" data-existing>Find existing product<input name="existingSearch" list="kai-s16-products" autocomplete="off" placeholder="Search name, category, club, code, size, version…"><datalist id="kai-s16-products">${list}</datalist></label><div class="excel-form-section" data-new>Product master</div><label data-new>Product code<input name="newId" placeholder="Leave blank to auto-create"></label><label data-new>Product name<input name="name" placeholder="Product description"></label><label data-new>Category<select name="category"><option value="">Choose category</option>${opts(CATEGORIES)}<option value="__custom__">Other / custom…</option></select></label><label data-new data-custom-category hidden>Custom category<input name="categoryCustom"></label><label data-new>Club / Country<input name="club"></label><label data-new>Version / Grade<select name="grade"><option value="">Choose version</option>${opts(VERSIONS)}<option value="__custom__">Other / custom…</option></select></label><label data-new data-custom-grade hidden>Custom version / grade<input name="gradeCustom"></label><label data-new>Home / Away / Third<select name="kit"><option value="">Choose</option>${opts(KITS)}<option value="__custom__">Other / custom…</option></select></label><label data-new data-custom-kit hidden>Custom kit / style<input name="kitCustom"></label><label data-new>Season<input name="season" placeholder="e.g. 2026/2027 or N/A"></label><label data-new>Colour<input name="color"></label><label data-new>Size<select name="size"><option value="">Choose size</option>${opts(SIZES)}<option value="__custom__">Other / custom…</option></select></label><label data-new data-custom-size hidden>Custom size<input name="sizeCustom"></label><label data-new>Minimum stock level<input name="minStock" type="number" min="0" step="1" value="5"></label><div class="excel-form-section">Delivery / stock-in</div><label>Destination counter<select name="device">${typeof allowedDevices==='function'?allowedDevices().map(d=>`<option value="${esc(d)}">${esc(typeof counterName==='function'?counterName(d):d)}</option>`).join(''):''}</select></label><label>Quantity received<input name="qty" type="number" min="1" step="1" value="1" required></label><label>Actual unit buying cost (UGX)<input name="cost" type="number" min="0" step="1" required></label><label>Supplier<input name="supplier"></label><label>Payment status<select name="paymentStatus">${opts(PAY,'Paid')}</select></label><label class="full">Remarks<input name="note"></label>`,async fd=>{
     const v=formDataValues(fd),q=Number(v.qty),cost=Number(v.cost);if(!Number.isInteger(q)||q<1)throw new Error('Enter quantity received');if(!Number.isFinite(cost)||cost<0)throw new Error('Enter actual buying cost');let id;
     if(v.kind==='new'){const name=String(v.name||'').trim(),category=custom(v,'category'),size=custom(v,'size'),grade=custom(v,'grade'),kit=custom(v,'kit');if(!name)throw new Error('Enter the product name');if(!category)throw new Error('Choose or enter a category');if(!size)throw new Error('Choose or enter a size');id=String(v.newId||'').trim()||(typeof newStockCode==='function'?newStockCode(name,size):`KW-${Date.now()}`);await onlineEvent('product',{id,name,category,club:String(v.club||'').trim(),grade,kit,season:String(v.season||'').trim(),color:String(v.color||'').trim(),size,minStock:Number(v.minStock||5),cost,retail:0,wholesale:0})}else{const p=resolveExisting(v.existingSearch);if(!p)throw new Error('Choose an existing product or switch to New product / variant');id=p.id}
     await onlineEvent('restock',{id,device:v.device,qty:q,cost,date:typeof now==='function'?now():new Date().toISOString(),supplier:String(v.supplier||'').trim(),paymentStatus:String(v.paymentStatus||'Paid'),note:String(v.note||'Stock received').trim()||'Stock received'});toast?.(v.kind==='new'?'New stock product added.':'Stock received successfully.');setTimeout(()=>{try{render()}catch(_){try{renderTable()}catch(__){}}},0)
   });
   setTimeout(()=>setupStockForm(kindDefault),0)
 }
 function setupStockForm(kindDefault){const form=document.querySelector('#dialog-form');if(!form)return;const kind=form.querySelector('[name="kind"]');const toggle=()=>{const isNew=kind?.value==='new';form.querySelectorAll('[data-new]').forEach(x=>x.hidden=!isNew);form.querySelectorAll('[data-existing]').forEach(x=>x.hidden=isNew)};if(kind){kind.value=kindDefault;kind.onchange=toggle}toggle();for(const n of ['category','grade','kit','size']){const s=form.querySelector(`[name="${n}"]`),lab=form.querySelector(`[data-custom-${n}]`);if(s&&lab){const t=()=>lab.hidden=s.value!=='__custom__';s.onchange=t;t()}}
   const read=form.querySelector('#kai-s16-read'),imp=form.querySelector('#kai-s16-import'),file=form.querySelector('#kai-s16-file'),statusEl=form.querySelector('#kai-s16-import-status'),preview=form.querySelector('#kai-s16-import-preview');if(read)read.onclick=async()=>{if(!file?.files?.[0]){statusEl.textContent='Choose an Excel or Word file first.';statusEl.className='kai-s16-status error';return}read.disabled=true;statusEl.textContent='Reading file…';try{const f=file.files[0],buf=new Uint8Array(await f.arrayBuffer());let bin='';for(let i=0;i<buf.length;i+=32768)bin+=String.fromCharCode(...buf.subarray(i,Math.min(i+32768,buf.length)));const r=await api('import-stock-preview',{filename:f.name,content:btoa(bin)});importRows=r.rows||[];statusEl.textContent=`${importRows.length} stock row${importRows.length===1?'':'s'} recognized.`;imp.disabled=!importRows.length;preview.style.display=importRows.length?'block':'none';preview.innerHTML=importRows.length?`<table><thead><tr><th>Code</th><th>Product</th><th>Category</th><th>Size</th><th class="end">Qty</th><th class="end">Cost</th></tr></thead><tbody>${importRows.slice(0,30).map(r=>`<tr><td>${esc(r.id||'')}</td><td>${esc(r.name||r.club||'')}</td><td>${esc(r.category||'')}</td><td>${esc(r.size||'')}</td><td class="end">${Number(r.qty||0)}</td><td class="end">${typeof money==='function'?money(Number(r.cost||0)):Number(r.cost||0)}</td></tr>`).join('')}</tbody></table>`:''}catch(e){importRows=[];statusEl.textContent=e.message;statusEl.className='kai-s16-status error';imp.disabled=true}finally{read.disabled=false}};if(imp)imp.onclick=async()=>{const device=form.querySelector('[name="device"]')?.value;if(!importRows.length||!device)return;imp.disabled=true;statusEl.textContent='Importing stock…';try{const r=await api('import-stock-commit',{device,rows:importRows});await sync();statusEl.textContent=`Import complete: ${r.imported} rows added; ${r.created} new variants created.`;toast?.('Stock file imported successfully');importRows=[];setTimeout(()=>{document.querySelector('#modal')?.close();try{render()}catch(_){}},250)}catch(e){statusEl.textContent=e.message;statusEl.className='kai-s16-status error';imp.disabled=false}}
 }
 restock=function(){openStockForm('existing')};addProduct=function(){openStockForm('new')};
 function mount(){if(!isStock())return;title();ensureCategoryFilter();mountSearch();renderTable()}
 document.addEventListener('kai:rendered',mount);
 document.addEventListener('click',e=>{if(!isStock())return;const b=e.target.closest?.('button');if(!b)return;const t=(b.textContent||'').trim().toLowerCase();if(t==='receive stock'||t==='receive / add stock'){e.preventDefault();e.stopPropagation();restock()}else if(t==='add product'||t==='add stock'||t==='add stock product'){e.preventDefault();e.stopPropagation();addProduct()}},true);
 setTimeout(mount,0)
})();
</script>
'''

pos=html.rfind('</body>')
if pos<0:raise RuntimeError('Final body tag not found')
html=html[:pos]+css+'\n'+js+'\n'+html[pos:]
index.write_text(html)
print('Kai Wear v16 seamless Stock runtime enabled.')
